// ChunkUpload .
// @router /chunk/upload/chunk/:upload_id/:chunk_index [POST]
func ChunkUpload(ctx context.Context, c *app.RequestContext) {
	var err error

	// 获取路径参数
	uploadID := c.Param("upload_id")
	chunkIndexStr := c.Param("chunk_index")

	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "上传ID不能为空",
		})
		return
	}

	chunkIndex, err := strconv.Atoi(chunkIndexStr)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "分片索引格式错误",
		})
		return
	}

	// 归属校验（治理）：防向他人会话覆盖分片（同尺寸分片可替换内容而不触发大小校验）。
	// 会话不存在必须 404 拒绝——2026-10-05 审计 P0：此前 `ierr == nil &&` 短路让
	// 不存在的 uploadID 跳过校验直接落盘（存储侧彼时无逃逸守卫，构成任意路径写）。
	if !validUploadID(uploadID) {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "上传ID格式非法",
		})
		return
	}
	info, ierr := getChunkService().GetUploadInfo(ctx, uploadID)
	if ierr != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "上传记录不存在",
		})
		return
	}
	if !ownedByCaller(info, c) {
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    errcode.CodeForbidden,
			"message": "无权操作该上传会话",
		})
		return
	}

	// 获取上传的文件
	file, err := c.FormFile("chunk")
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "请上传分片文件",
		})
		return
	}

	// 读取文件内容
	src, err := file.Open()
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "读取文件失败: " + err.Error(),
		})
		return
	}
	defer func() { _ = src.Close() }()

	// 读取文件数据到内存
	data := make([]byte, file.Size)
	_, err = io.ReadFull(src, data)
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "读取文件内容失败: " + err.Error(),
		})
		return
	}

	// 计算分片哈希
	hash := md5.Sum(data)
	chunkHash := hex.EncodeToString(hash[:])

	// 分片期望哈希强校验（对齐上游逐片验证；可选参数 hash：32 位=MD5 / 64 位=SHA-256）。
	// 客户端携带时做恒时比对，不符即拒收该分片（422 retryable）——传输损坏/代理改写
	// 被限定在单片内，客户端重传该分片即可；未携带时保持旧行为（仅记录服务端 MD5）。
	if expected := expectedChunkHash(c); expected != "" {
		digest := chunkHash
		switch len(expected) {
		case 64:
			s := sha256.Sum256(data)
			digest = hex.EncodeToString(s[:])
		case 32:
			// chunkHash 已是 MD5
		default:
			expected = "" // 未知长度不校验（可选项不破坏上传）
		}
		if expected != "" && subtle.ConstantTimeCompare([]byte(digest), []byte(expected)) != 1 {
			c.JSON(consts.StatusUnprocessableEntity, map[string]interface{}{
				"code":    errcode.CodeChunkInvalid,
				"message": "分片哈希校验失败，请重试该分片",
				"data":    map[string]interface{}{"chunk_index": chunkIndex, "retryable": true},
			})
			return
		}
	}

	// 保存分片到存储
	err = getChunkService().SaveChunkData(ctx, uploadID, chunkIndex, data)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "保存分片失败: " + err.Error(),
		})
		return
	}

	// 记录分片上传信息
	uploadReq := &chunkService.UploadChunkReq{
		UploadID:   uploadID,
		ChunkIndex: chunkIndex,
		ChunkHash:  chunkHash,
		ChunkSize:  int(file.Size),
	}

	result, err := getChunkService().UploadChunk(ctx, uploadReq)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "记录分片信息失败: " + err.Error(),
		})
		return
	}

	resp := &chunkmodel.ChunkUploadResp{
		Code:    0,
		Message: "分片上传成功",
		Data: &chunkmodel.ChunkUploadData{
			ChunkIndex: int32(result.ChunkIndex),
			ChunkHash:  result.ChunkHash,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// ChunkUploadStatus .
// @router /chunk/upload/status/:upload_id [GET]
func ChunkUploadStatus(ctx context.Context, c *app.RequestContext) {
	var err error

	// 获取上传ID
	uploadID := c.Param("upload_id")
	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "上传ID不能为空",
		})
		return
	}

	// 获取上传信息
	info, err := getChunkService().GetUploadInfo(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "上传记录不存在",
		})
		return
	}

	// 归属校验（治理）：会话元数据（文件名/进度）不向第三方泄露
	if !ownedByCaller(info, c) {
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    errcode.CodeForbidden,
			"message": "无权操作该上传会话",
		})
		return
	}

	// 获取已上传分片索引
	uploadedIndexes, err := getChunkService().GetUploadedChunkIndexes(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "获取上传进度失败: " + err.Error(),
		})
		return
	}

	// 计算进度
	var progress float64
	if info.TotalChunks > 0 {
		progress = float64(len(uploadedIndexes)) / float64(info.TotalChunks) * 100
	}

	// 确定状态
	status := "uploading"
	if len(uploadedIndexes) == info.TotalChunks {
		status = "completed"
	} else if len(uploadedIndexes) == 0 {
		status = "pending"
	}

	// 转换索引数组
	uploadedIndexes32 := make([]int32, len(uploadedIndexes))
	for i, idx := range uploadedIndexes {
		uploadedIndexes32[i] = int32(idx)
	}

	resp := &chunkmodel.ChunkUploadStatusResp{
		Code:    0,
		Message: "获取成功",
		Data: &chunkmodel.ChunkUploadStatusData{
			UploadID:        info.UploadID,
			TotalChunks:     int32(info.TotalChunks),
			UploadedChunks:  int32(len(uploadedIndexes)),
			UploadedIndexes: uploadedIndexes32,
			Progress:        int32(progress),
			Status:          status,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// chunkSessionToken/verifyChunkToken/ownedByCaller 收敛为 app/chunk 单一实现的
// 薄委托（此前与 transport/handler/share_multi.go 逐字孪生）。

func chunkSessionToken(uploadID string) string {
	return chunkService.SessionToken(uploadID)
}

func verifyChunkToken(uploadID, token string) bool {
	return chunkService.VerifySessionToken(uploadID, token)
}

// expectedChunkHash 读取客户端期望的分片哈希：query 优先、multipart form 兜底。
// 空串表示未携带（跳过校验，保持旧行为）。
func expectedChunkHash(c *app.RequestContext) string {
	if h := strings.ToLower(c.Query("hash")); h != "" {
		return h
	}
	return strings.ToLower(string(c.FormValue("hash")))
}

// ownedByCaller 归属校验（身份从 c.Get 提取，与本组中间件注入路径一致）
func ownedByCaller(info *model.UploadChunk, c *app.RequestContext) bool {
	var callerUserID *uint
	if uid, exists := c.Get("user_id"); exists {
		if uidUint, ok := uid.(uint); ok {
			callerUserID = &uidUint
		}
	}
	return chunkService.OwnedByCaller(info, middleware.ClientIP(c), string(c.GetHeader("X-Upload-Token")), callerUserID)
}

// validUploadID 上传ID字符白名单：合法来源仅 UUID 与 MD5/SHA-256 十六进制
// （客户端可自报哈希），字母数字+连字符/下划线、≤128 位。点号整体排除——
// 从词法上根除 `..`/`.` 之类路径语义进入存储 key（chunks/<id>/chunk_N）的可能。
// 2026-10-05 审计 P0：无此校验时 uploadID 携 `..` 可越出 data 根写/删文件。
func validUploadID(id string) bool {
	if id == "" || len(id) > 128 {
		return false
	}
	for _, r := range id {
		switch {
		case r >= '0' && r <= '9':
		case r >= 'a' && r <= 'z':
		case r >= 'A' && r <= 'Z':
		case r == '-' || r == '_':
		default:
			return false
		}
	}
	return true
}

// ChunkUploadComplete .
// @router /chunk/upload/complete/:upload_id [POST]
func ChunkUploadComplete(ctx context.Context, c *app.RequestContext) {
	var err error

	// 获取上传ID
	uploadID := c.Param("upload_id")
	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "上传ID不能为空",
		})
		return
	}

	// 解析请求参数
	var req chunkmodel.ChunkUploadCompleteReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": err.Error(),
		})
		return
	}

	// 获取上传信息
	info, err := getChunkService().GetUploadInfo(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "上传记录不存在",
		})
		return
	}

	// 归属校验（治理）：仅归属方可 Complete，防猜中 uploadID 劫持他人上传会话
	if !ownedByCaller(info, c) {
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    errcode.CodeForbidden,
			"message": "无权操作该上传会话",
		})
		return
	}

	// 幂等：同一 upload_id 已建过分享 ⇒ **复用**（不新建行、不重复扣次、
	// 不重复计配额，**也不再合并出第二份物理文件**）。
	//
	// 缺陷（2026-10-24 审计，core v0.32.6）：此前 Complete **不检查**是否已建过
	// 分享 ⇒ 双击 / 客户端重试 / 网络重试 二次 complete 同一 upload_id 会
	// **再建一条分享**：两个分享各有独立的取件次数额度与取件码 ⇒ owner 设的
	// 「最多取 N 次」实际可取 2N 次；用户存储统计也被双计；每次合并还会生成新的
	// UUID 物理路径 ⇒ **磁盘上留下第二份**（仅 Cancel 回收分片）。
	// 真机实测：13 条带 upload_id 的分享里已有 **1 组重复** ⇒ 已在生产数据发生。
	//
	// 位置在**合并之前**：重试不该再把分片合并一遍（浪费 IO + 多一份物理文件）。
	if existing, ferr := getShareService().FindShareByUploadID(ctx, uploadID); ferr == nil && existing != nil {
		// 会话状态可能没同步（上次 ShareFile 成功但 CompleteUpload 失败）⇒ 补标记
		_ = getChunkService().CompleteUpload(ctx, uploadID)
		c.JSON(consts.StatusOK, &chunkmodel.ChunkUploadCompleteResp{
			Code:    0,
			Message: "上传完成",
			Data: &chunkmodel.ChunkUploadCompleteData{
				ShareCode: existing.Code,
				ShareURL:  chunkSharePageURL(ctx, existing.Code),
				FileName:  info.FileName,
				FileSize:  info.FileSize,
			},
		})
		return
	}

	// 检查所有分片是否已上传
	uploadedIndexes, err := getChunkService().GetUploadedChunkIndexes(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "检查上传状态失败: " + err.Error(),
		})
		return
	}

	if len(uploadedIndexes) < info.TotalChunks {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": fmt.Sprintf("还有 %d 个分片未上传", info.TotalChunks-len(uploadedIndexes)),
		})
		return
	}

	// 合并分片（磁盘布局与合并操作收口 app/chunk，与直传落盘同源）
	relativePath, err := getChunkService().MergeUpload(ctx, uploadID, info.TotalChunks, info.FileName)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "合并分片失败: " + err.Error(),
		})
		return
	}

	// 计算合并后整文件 SHA-256（秒传依据；此前恒以 uploadID 冒充 file_hash）。
	// 回归要点：必须经注入的 storage 实例读取（与合并写入同基 + resolveLocal
	// 历史布局兼容），不能硬编码 "./data"——统一存储实例后基已变，硬编码读不到
	// → file_hash 恒空 → 分片通道秒传永不命中。
	var head []byte
	fileHash := ""
	var actualSize int64
	if rc, fsize, rerr := getChunkService().OpenMerged(ctx, relativePath); rerr == nil {
		actualSize = fsize
		// 先读 512 字节做魔数复检，再以 MultiReader 把头部拼回流算整文件哈希
		//（ReadCloser 不保证可 Seek，不能回卷）
		head = readHeadFrom(rc, 512)
		fileHash, _ = utils.HashReader(io.MultiReader(bytes.NewReader(head), rc))
		_ = rc.Close()
	}
	if fileHash == "" {
		// 哈希失败不阻断分享创建（仅失去秒传能力），记空
		fmt.Println("计算文件哈希失败（分享创建继续，仅失去秒传能力）")
	}

	// E2E 客户端加密（P1）：客户端上传的已是密文，跳过魔数复检（密文头为随机字节）。
	// encrypted 走 JSON body（契约 api.body）——旧的 form 通道已删（2026-10-25 删除旧版本兼容）
	encrypted := false
	var encBody struct {
		Encrypted bool `json:"encrypted"`
	}
	if b := c.Request.Body(); len(b) > 0 {
		_ = json.Unmarshal(b, &encBody)
		encrypted = encBody.Encrypted
	}

	// 魔数+扩展名复检（首分片可能绕过 init 校验；E2E 密文跳过）
	if !encrypted && head != nil {
		if err := utils.CheckUploadContent(info.FileName, head); err != nil {
			getChunkService().DeleteMergedFile(ctx, relativePath)
			_ = getChunkService().DeleteUpload(ctx, uploadID)
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeFileTypeDenied,
				"message": err.Error(),
			})
			return
		}
	}

	// 完整性复查：合并后实际大小 vs 上限/申报（修复：init 自报 FileSize 从未被复核，
	// 可申报 1KB 实传任意大文件绕过 max_file_size；申报不符说明分片丢失或被篡改）
	if actualSize > 0 {
		if maxFile := utils.GetMaxFileSize(); maxFile > 0 && actualSize > maxFile {
			getChunkService().DeleteMergedFile(ctx, relativePath)
			_ = getChunkService().DeleteUpload(ctx, uploadID)
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeTooLarge,
				"message": fmt.Sprintf("合并后文件大小 %d 字节超过上限 %d 字节", actualSize, maxFile),
			})
			return
		}
		if info.FileSize > 0 && actualSize != info.FileSize {
			getChunkService().DeleteMergedFile(ctx, relativePath)
			_ = getChunkService().DeleteUpload(ctx, uploadID)
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeChunkInvalid,
				"message": fmt.Sprintf("合并后文件大小 %d 与申报大小 %d 不符", actualSize, info.FileSize),
			})
			return
		}
	}

	// 计算过期时间
	if err := utils.CheckExpireStyleAllowed(req.ExpireStyle); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": err.Error(),
		})
		return
	}
	expireTime := utils.CalculateExpireTime(int(req.ExpireValue), req.ExpireStyle)
	expireCount := utils.CalculateExpireCount(req.ExpireStyle, int(req.ExpireValue))

	// 获取用户ID（如果有）
	var userID *uint
	if uid, exists := c.Get("user_id"); exists {
		if uidUint, ok := uid.(uint); ok {
			userID = &uidUint
		}
	}

	// 获取客户端 IP（可信代理解析）
	ownerIP := middleware.ClientIP(c)

	// 确定上传类型
	uploadType := "anonymous"
	if userID != nil {
		uploadType = "authenticated"
	}

	// 密码保护（修复 P0：此前 RequireAuth 透传但密码丢失，产出
	// require_auth=true 且哈希为空的死分享——取件侧对空哈希一律拒绝，
	// 分享永远无法取件）。契约字段（v0.6.2 起；此前 form 直读+二次解析 body）。
	passwordHash := ""
	if req.RequireAuth {
		password := ""
		if req.Password != nil {
			password = *req.Password
		}
		if password == "" {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeInvalidParam,
				"message": "开启密码保护时必须提供密码",
			})
			return
		}
		hash, pwErr := utils.HashPassword(password)
		if pwErr != nil {
			c.JSON(consts.StatusInternalServerError, map[string]interface{}{
				"code":    errcode.CodeInternal,
				"message": "密码处理失败",
			})
			return
		}
		passwordHash = hash
	}

	// 自定义取件码（P3）：仅登录用户可指定（防匿名抢注）
	customCode := ""
	if userID != nil && req.CustomCode != nil {
		customCode = *req.CustomCode
	}
	note := ""
	if req.Note != nil {
		note = *req.Note
	}

	// 创建分享记录
	shareReq := &shareService.ShareFileReq{
		Channel:      "chunk",
		FilePath:     relativePath,
		Size:         info.FileSize,
		Text:         utils.SanitizeFileName(info.FileName),
		ExpiredAt:    expireTime,
		ExpiredCount: expireCount,
		RequireAuth:  req.RequireAuth,
		PasswordHash: passwordHash,
		UserID:       userID,
		UploadType:   uploadType,
		OwnerIP:      ownerIP,
		FileHash:     fileHash,
		IsChunked:    true,
		UploadID:     uploadID,
		Encrypted:    encrypted,
		CustomCode:   customCode,
		Note:         note,
	}

	shareResult, err := getShareService().ShareFile(ctx, shareReq)
	if err != nil {
		resp.NewTypedError(c, err) // 配额/单次上限/审核等 typed error 按业务码透传
		return
	}

	// 更新上传状态为完成
	err = getChunkService().CompleteUpload(ctx, uploadID)
	if err != nil {
		// 记录错误但不影响返回结果
		fmt.Printf("更新上传状态失败: %v\n", err)
	}

	// 生成分享URL（hash 路由的页面链接）。
	// 回归：此前经 PublicBaseURL 兜底静态拼 server.host:port（更早恒用
	// localhost:12345 常量）——0.0.0.0/localhost 链接对外均不可达，现与
	// share service 同策略（请求来源动态推断，详见 publicShareURL）。
	//
	// 不再附下载令牌：令牌拼在 hash 形态 URL 之后会落进 fragment，服务端
	// 收不到、分享页前端也不读 route.query.token ⇒ 令牌形同虚设且误导
	// （2026-10-23 跨仓审计）。要带令牌的直链走 /share/select 下发的
	// download_url（与 /share/file/ 等其它上传路径口径一致）。
	fullShareURL := chunkSharePageURL(ctx, shareResult.Code)

	resp := &chunkmodel.ChunkUploadCompleteResp{
		Code:    0,
		Message: "上传完成",
		Data: &chunkmodel.ChunkUploadCompleteData{
			ShareCode: shareResult.Code,
			ShareURL:  fullShareURL,
			FileName:  info.FileName,
			FileSize:  info.FileSize,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// readHeadFrom 从 reader 读取前 n 字节（魔数校验用）；读取失败返回 nil
func readHeadFrom(r io.Reader, n int) []byte {
	buf := make([]byte, n)
	read, err := io.ReadFull(r, buf)
	if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
		return nil
	}
	return buf[:read]
}

// ChunkUploadCancel .
// @router /chunk/upload/cancel/:upload_id [DELETE]
func ChunkUploadCancel(ctx context.Context, c *app.RequestContext) {
	// 获取上传ID
	uploadID := c.Param("upload_id")
	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "上传ID不能为空",
		})
		return
	}

	// 归属校验（治理）：防第三方取消/删除他人分片。
	// 会话不存在必须 404 拒绝——2026-10-05 审计 P0：此前 `ierr == nil &&` 短路
	// 让不存在的 uploadID 跳过校验直达 CleanSessionFiles，uploadID 携 `..` 时
	// RemoveAll(chunks/..) 即删整个 data 根（库+全部上传文件）。
	if !validUploadID(uploadID) {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "上传ID格式非法",
		})
		return
	}
	info, ierr := getChunkService().GetUploadInfo(ctx, uploadID)
	if ierr != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "上传记录不存在",
		})
		return
	}
	if !ownedByCaller(info, c) {
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    errcode.CodeForbidden,
			"message": "无权操作该上传会话",
		})
		return
	}

	// 删除分片存储
	err := getChunkService().CleanSessionFiles(ctx, uploadID)
	if err != nil {
		fmt.Printf("清理分片文件失败: %v\n", err)
	}

	// 删除上传记录
	err = getChunkService().DeleteUpload(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "取消上传失败: " + err.Error(),
		})
		return
	}

	resp := &chunkmodel.ChunkUploadCancelResp{
		Code:    0,
		Message: "上传已取消",
	}

	c.JSON(consts.StatusOK, resp)
}
